  1→"use client";
  2→
  3→/**
  4→ * Sidebar listing all agents with status dots, truncated labels,
  5→ * tmux session names, and a "+" button to spawn a new agent.
  6→ *
  7→ * Split into two sections:
  8→ * - **Active**: agents with status `spawning`, `connected`, or `thinking`.
  9→ * - **Archived**: agents with status `done`, `disconnected`, or `error` (read-only).
 10→ *
 11→ * Right-click (or kebab icon) context menu supports: Rename, Kill, Clear History, Delete.
 12→ * Rename swaps the label for an inline input.
 13→ */
 14→
 15→import { useCallback, useEffect, useRef, useState } from "react";
 16→import { EllipsisVertical, Plus } from "lucide-react";
 17→import type { AgentStatus, Workspace } from "@/lib/types";
 18→import type { AgentClientState } from "@/hooks/use-websocket";
 19→import { cn } from "@/lib/utils";
 20→import { WorkspaceSwitcher } from "./workspace-switcher";
 21→
 22→/** Status dot color + optional pulse animation. */
 23→const STATUS_DOT: Record<AgentStatus, string> = {
 24→  idle: "bg-muted-foreground",
 25→  spawning: "bg-yellow-500 animate-pulse",
 26→  connected: "bg-green-500",
 27→  thinking: "bg-blue-500 animate-pulse",
 28→  done: "bg-muted-foreground",
 29→  disconnected: "bg-orange-500 animate-pulse",
 30→  error: "bg-red-500",
 31→};
 32→
 33→/** Statuses where the CLI is actively running and can be killed. */
 34→const KILLABLE: Set<AgentStatus> = new Set(["spawning", "connected", "thinking"]);
 35→/** Statuses considered archived (session ended, read-only). */
 36→const ARCHIVED: Set<AgentStatus> = new Set(["done", "disconnected", "error"]);
 37→
 38→interface ContextMenuState {
 39→  agentId: string;
 40→  x: number;
 41→  y: number;
 42→}
 43→
 44→export function AgentSidebar({
 45→  agents,
 46→  agentOrder,
 47→  activeAgentId,
 48→  loading,
 49→  onSelect,
 50→  onNewAgent,
 51→  onKill,
 52→  onDelete,
 53→  onRename,
 54→  onClearHistory,
 55→  workspaces,
 56→  activeWorkspaceId,
 57→  onSelectWorkspace,
 58→  onRenameWorkspace,
 59→  onDeleteWorkspace,
 60→  onOpenFolder,
 61→}: {
 62→  agents: Map<string, AgentClientState>;
 63→  agentOrder: string[];
 64→  activeAgentId: string | null;
 65→  loading?: boolean;
 66→  onSelect: (agentId: string | null) => void;
 67→  onNewAgent: () => void;
 68→  onKill: (agentId: string) => void;
 69→  onDelete: (agentId: string) => void;
 70→  onRename: (agentId: string, label: string) => void;
 71→  onClearHistory: (agentId: string) => void;
 72→  workspaces: Workspace[];
 73→  activeWorkspaceId: string | null;
 74→  onSelectWorkspace: (workspaceId: string | null) => void;
 75→  onRenameWorkspace: (workspaceId: string, name: string) => void;
 76→  onDeleteWorkspace: (workspaceId: string) => void;
 77→  onOpenFolder: () => void;
 78→}) {
 79→  const [ctxMenu, setCtxMenu] = useState<ContextMenuState | null>(null);
 80→  const [renamingId, setRenamingId] = useState<string | null>(null);
 81→  const menuRef = useRef<HTMLDivElement>(null);
 82→
 83→  // Split agents into active and archived
 84→  const activeIds = agentOrder.filter((id) => {
 85→    const a = agents.get(id);
 86→    return a && !ARCHIVED.has(a.status);
 87→  });
 88→  const archivedIds = agentOrder.filter((id) => {
 89→    const a = agents.get(id);
 90→    return a && ARCHIVED.has(a.status);
 91→  });
 92→
 93→  // Close context menu on click-outside or Escape
