  onClearHistory,
  showTasks,
  onToggleTasks,
  showDiffs,
  onToggleDiffs,
  onToggleSidebar,
  onOpenSfxSettings,
}: {
  connected: boolean;
  loading?: boolean;
  status: AgentStatus;
  messages: ChatMessage[];
  rawMessages: ClaudeMessage[];
  activeModel?: string | null;
  selectedModel?: string;
  onModelChange?: (model: string) => void;
  onSendMessage: (content: string) => void;
  onSpawnAgent: (prompt: string) => void;
  onRespondToControl: (requestId: string, allow: boolean) => void;
  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
  onClearHistory?: () => void;
  showTasks?: boolean;
  onToggleTasks?: () => void;
  showDiffs?: boolean;
  onToggleDiffs?: () => void;
  onToggleSidebar?: () => void;
  onOpenSfxSettings?: () => void;
}) {
  const [input, setInput] = useState("");
  const [showRaw, setShowRaw] = useState(false);
  const [showSlashMenu, setShowSlashMenu] = useState(false);
  const [slashQuery, setSlashQuery] = useState("");
  const [slashHighlight, setSlashHighlight] = useState(0);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo({
      top: scrollRef.current.scrollHeight,
      behavior: "smooth",
    });
  }, [messages, rawMessages, showRaw]);

  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
  const isActive = status === "connected" || status === "thinking";
  const isArchived = status === "done" || status === "disconnected" || status === "error";

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    const trimmed = input.trim();
    if (!trimmed) return;

    if (isActive) {
      onSendMessage(trimmed);
    } else {
      onSpawnAgent(trimmed);
    }
    setInput("");
    setShowSlashMenu(false);
  }

  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
    const value = e.target.value;
    setInput(value);

    if (value.startsWith("/")) {
      setShowSlashMenu(true);
      setSlashQuery(value.slice(1));
      setSlashHighlight(0);
    } else {
      setShowSlashMenu(false);
      setSlashQuery("");
    }
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (!showSlashMenu) return;
    const filtered = filterCommands(slashQuery);
    if (filtered.length === 0) return;

    if (e.key === "ArrowDown") {
      e.preventDefault();
      setSlashHighlight((i) => (i + 1) % filtered.length);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
    } else if (e.key === "Enter") {
      e.preventDefault();
      handleCommandSelect(filtered[slashHighlight]);
    } else if (e.key === "Escape") {
      e.preventDefault();
      setShowSlashMenu(false);
    } else if (e.key === "Tab") {
      e.preventDefault();
      setInput(`/${filtered[slashHighlight].name} `);
      setShowSlashMenu(false);
    }
  }

  function handleCommandSelect(command: SlashCommand) {
    setShowSlashMenu(false);
    setSlashQuery("");
    setInput("");

    if (command.clientSide) {
      if (command.name === "clear") {
        onClearHistory?.();
      }
      return;
    }

    const commandText = `/${command.name}`;
    if (isActive) {
      onSendMessage(commandText);
    } else {
      onSpawnAgent(commandText);
    }
  }

  return (
    <div className="flex h-full flex-col">
      <StatusBar
        connected={connected}
        status={status}
        activeModel={activeModel}
        selectedModel={selectedModel}
        onModelChange={onModelChange}
        showRaw={showRaw}
        onToggleRaw={() => setShowRaw((v) => !v)}
        showTasks={showTasks}
        onToggleTasks={onToggleTasks}
        showDiffs={showDiffs}
        onToggleDiffs={onToggleDiffs}
        onToggleSidebar={onToggleSidebar}
        onOpenSfxSettings={onOpenSfxSettings}
