  1→"use client";
  2→
  3→/**
  4→ * Top bar showing the WS connection state (green/red dot), the current
  5→ * agent lifecycle status, active model name, and a model selector dropdown.
  6→ */
  7→
  8→import { useEffect, useRef, useState } from "react";
  9→import { ChevronDown, GitCompareArrows, ListTodo, Menu, Volume2 } from "lucide-react";
 10→import { Button } from "@/components/ui/button";
 11→import { cn } from "@/lib/utils";
 12→import type { AgentStatus } from "@/lib/types";
 13→
 14→/** Human-readable labels for each agent status. */
 15→const STATUS_LABELS: Record<AgentStatus, string> = {
 16→  idle: "idle",
 17→  spawning: "spawning...",
 18→  connected: "connected",
 19→  thinking: "thinking...",
 20→  done: "done",
 21→  disconnected: "disconnected",
 22→  error: "error",
 23→};
 24→
 25→/** Curated list of common models for the dropdown. */
 26→const MODEL_PRESETS = [
 27→  { value: "", label: "Default (CLI)", description: "Use CLI default model" },
 28→  { value: "claude-sonnet-4-20250514", label: "Sonnet 4", description: "Claude Sonnet 4" },
 29→  { value: "claude-opus-4-20250514", label: "Opus 4", description: "Claude Opus 4" },
 30→  { value: "qwen3-coder", label: "Qwen3 Coder", description: "Ollama — Qwen3 Coder" },
 31→  { value: "devstral", label: "Devstral", description: "Ollama — Devstral" },
 32→];
 33→
 34→export function StatusBar({
 35→  connected,
 36→  status,
 37→  agentLabel,
 38→  activeModel,
 39→  selectedModel,
 40→  onModelChange,
 41→  showRaw,
 42→  onToggleRaw,
 43→  showTasks,
 44→  onToggleTasks,
 45→  showDiffs,
 46→  onToggleDiffs,
 47→  onToggleSidebar,
 48→  onOpenSfxSettings,
 49→}: {
 50→  connected: boolean;
 51→  status: AgentStatus;
 52→  agentLabel?: string | null;
 53→  activeModel?: string | null;
 54→  selectedModel?: string;
 55→  onModelChange?: (model: string) => void;
 56→  showRaw?: boolean;
 57→  onToggleRaw?: () => void;
 58→  showTasks?: boolean;
 59→  onToggleTasks?: () => void;
 60→  showDiffs?: boolean;
 61→  onToggleDiffs?: () => void;
 62→  onToggleSidebar?: () => void;
 63→  onOpenSfxSettings?: () => void;
 64→}) {
 65→  const [dropdownOpen, setDropdownOpen] = useState(false);
 66→  const [customInput, setCustomInput] = useState("");
 67→  const [showCustom, setShowCustom] = useState(false);
 68→  const dropdownRef = useRef<HTMLDivElement>(null);
 69→  const customInputRef = useRef<HTMLInputElement>(null);
 70→
 71→  // Close dropdown on click-outside or Escape
 72→  useEffect(() => {
 73→    if (!dropdownOpen) return;
 74→    function handleClick(e: MouseEvent) {
 75→      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
 76→        setDropdownOpen(false);
 77→        setShowCustom(false);
 78→      }
 79→    }
 80→    function handleKey(e: KeyboardEvent) {
 81→      if (e.key === "Escape") {
 82→        setDropdownOpen(false);
 83→        setShowCustom(false);
 84→      }
 85→    }
 86→    document.addEventListener("mousedown", handleClick);
 87→    document.addEventListener("keydown", handleKey);
 88→    return () => {
 89→      document.removeEventListener("mousedown", handleClick);
 90→      document.removeEventListener("keydown", handleKey);
 91→    };
 92→  }, [dropdownOpen]);
 93→
 94→  // Focus custom input when it appears
 95→  useEffect(() => {
 96→    if (showCustom) customInputRef.current?.focus();
 97→  }, [showCustom]);
 98→
 99→  /** Shorten a model name for display (e.g. "claude-sonnet-4-20250514" → "sonnet-4"). */
100→  function shortModel(model: string): string {
101→    // Match known preset labels
102→    const preset = MODEL_PRESETS.find((p) => p.value === model);
103→    if (preset && preset.value) return preset.label;
104→    // Strip "claude-" prefix and date suffix for Claude models
105→    const m = model.replace(/^claude-/, "").replace(/-\d{8}$/, "");
106→    return m || model;
107→  }
108→
109→  const displayModel = activeModel ?? (selectedModel || null);
110→  const isActive = status === "connected" || status === "thinking";
111→
112→  return (
113→    <div className="flex items-center justify-between border-b px-2 py-2 text-xs md:px-4">
114→      {/* Left side */}
115→      <div className="flex items-center gap-2">
116→        {onToggleSidebar && (
117→          <button
118→            onClick={onToggleSidebar}
119→            className="rounded p-1 transition-colors hover:bg-muted/50 md:hidden"
120→            aria-label="Toggle sidebar"
121→          >
122→            <Menu className="size-4" />
123→          </button>
124→        )}
125→        <span className="text-muted-foreground font-semibold hidden md:inline">thos dashboard</span>
126→        <span className="text-muted-foreground font-semibold md:hidden">thos</span>
127→        {agentLabel && (
128→          <>
129→            <span className="text-muted-foreground/50">/</span>
130→            <span className="truncate max-w-[150px] md:max-w-[250px] font-medium text-foreground/80">{agentLabel}</span>
131→          </>
132→        )}
133→      </div>
134→
135→      {/* Right side */}
136→      <div className="flex items-center gap-1.5 md:gap-3">
137→        <span className="flex items-center gap-1.5">
138→          <span
139→            className={`inline-block size-2 rounded-full ${
140→              connected ? "bg-green-500" : "bg-red-500"
141→            }`}
142→          />
143→          <span className="hidden md:inline">
144→            {connected ? "ws connected" : "ws disconnected"}
145→          </span>
146→        </span>
147→        <span className="text-muted-foreground hidden md:inline">|</span>
148→        <span className="hidden md:inline">agent: {STATUS_LABELS[status]}</span>
149→        <span className="text-[10px] md:hidden">{STATUS_LABELS[status]}</span>
150→
151→        {/* Model display + selector */}
152→        {onModelChange && (
153→          <>
154→            <span className="text-muted-foreground hidden md:inline">|</span>
155→            <div className="relative" ref={dropdownRef}>
156→              <button
157→                onClick={() => setDropdownOpen((v) => !v)}
158→                className={cn(
159→                  "flex items-center gap-1 rounded px-1.5 py-0.5 font-mono transition-colors",
160→                  "hover:bg-muted/80 text-muted-foreground",
161→                  dropdownOpen && "bg-muted"
162→                )}
163→                title={displayModel ? `Model: ${displayModel}` : "Select model for next spawn"}
164→              >
165→                <span className="max-w-[120px] truncate text-[10px] md:text-xs md:max-w-[180px]">
166→                  {displayModel ? shortModel(displayModel) : "model"}
167→                </span>
168→                <ChevronDown className="size-3 shrink-0" />
169→              </button>
170→
171→              {dropdownOpen && (
172→                <div className="absolute right-0 top-full z-50 mt-1 min-w-[220px] rounded-md border bg-popover p-1 shadow-md">
173→                  {isActive && activeModel && (
174→                    <div className="px-2 py-1.5 text-[10px] text-muted-foreground border-b mb-1">
175→                      Active: <span className="font-mono">{activeModel}</span>
176→                    </div>
177→                  )}
178→                  <div className="px-2 py-1 text-[10px] text-muted-foreground uppercase tracking-wider">
179→                    Next spawn
180→                  </div>
181→                  {MODEL_PRESETS.map((preset) => (
182→                    <button
183→                      key={preset.value}
184→                      onClick={() => {
185→                        onModelChange(preset.value);
186→                        setDropdownOpen(false);
187→                        setShowCustom(false);
188→                      }}
189→                      className={cn(
190→                        "flex w-full flex-col rounded px-2 py-1.5 text-left transition-colors hover:bg-accent",
191→                        selectedModel === preset.value && "bg-accent"
192→                      )}
193→                    >
194→                      <span className="text-xs font-medium">{preset.label}</span>
195→                      <span className="text-[10px] text-muted-foreground">{preset.description}</span>
196→                    </button>
197→                  ))}
198→                  <div className="my-1 border-t" />
199→                  {showCustom ? (
200→                    <form
201→                      onSubmit={(e) => {
202→                        e.preventDefault();
203→                        const val = customInput.trim();
204→                        if (val) {
205→                          onModelChange(val);
206→                          setCustomInput("");
207→                          setShowCustom(false);
208→                          setDropdownOpen(false);
209→                        }
210→                      }}
211→                      className="px-2 py-1"
212→                    >
213→                      <input
214→                        ref={customInputRef}
215→                        type="text"
216→                        value={customInput}
217→                        onChange={(e) => setCustomInput(e.target.value)}
218→                        placeholder="e.g. llama3.3:70b"
219→                        className="w-full rounded border bg-background px-2 py-1 text-xs outline-none focus:ring-1 focus:ring-ring"
220→                      />
221→                    </form>
222→                  ) : (
223→                    <button
224→                      onClick={() => setShowCustom(true)}
225→                      className="flex w-full rounded px-2 py-1.5 text-left text-xs text-muted-foreground transition-colors hover:bg-accent"
226→                    >
227→                      Custom model...
228→                    </button>
229→                  )}
230→                </div>
231→              )}
232→            </div>
233→          </>
234→        )}
235→
236→        <span className="text-muted-foreground hidden md:inline">|</span>
237→        <div className="flex items-center gap-1.5">
238→          {onToggleRaw && (
239→            <button
240→              onClick={onToggleRaw}
241→              className={cn(
242→                "rounded px-2 py-0.5 text-[10px] font-mono transition-colors",
243→                showRaw
244→                  ? "bg-foreground text-background"
245→                  : "bg-muted text-muted-foreground hover:bg-muted/80"
246→              )}
247→            >
248→              {showRaw ? "RAW" : "raw"}
249→            </button>
250→          )}
251→          {onToggleDiffs && (
252→            <Button
253→              variant="ghost"
254→              size="icon-xs"
255→              onClick={onToggleDiffs}
256→              title="Toggle diffs"
257→              className={cn(showDiffs && "text-primary")}
258→            >
259→              <GitCompareArrows className="size-3.5" />
260→            </Button>
261→          )}
262→          {onToggleTasks && (
263→            <Button
264→              variant="ghost"
265→              size="icon-xs"
266→              onClick={onToggleTasks}
267→              title="Toggle tasks"
268→              className={cn(showTasks && "text-primary")}
269→            >
270→              <ListTodo className="size-3.5" />
271→            </Button>
272→          )}
273→          {onOpenSfxSettings && (
274→            <Button
275→              variant="ghost"
276→              size="icon-xs"
277→              onClick={onOpenSfxSettings}
278→              title="Sound settings"
279→            >
280→              <Volume2 className="size-3.5" />
281→            </Button>
282→          )}
283→        </div>
284→      </div>
285→    </div>
286→  );
287→}
