  1→"use client";
  2→
  3→import { useState } from "react";
  4→import { Play, Pencil, Trash2, ExternalLink, Check } from "lucide-react";
  5→import { Button } from "@/components/ui/button";
  6→import { cn } from "@/lib/utils";
  7→import type { Task, TaskStatus, TaskPriority } from "@/lib/types";
  8→
  9→const PRIORITY_COLORS: Record<TaskPriority, string> = {
 10→  urgent: "bg-red-500/20 text-red-400 border-red-500/30",
 11→  high: "bg-orange-500/20 text-orange-400 border-orange-500/30",
 12→  medium: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
 13→  low: "bg-muted text-muted-foreground border-border",
 14→};
 15→
 16→const STATUS_COLORS: Record<TaskStatus, string> = {
 17→  icebox: "bg-purple-500/20 text-purple-400 border-purple-500/30",
 18→  todo: "border-border text-muted-foreground",
 19→  "in-progress": "bg-blue-500/20 text-blue-400 border-blue-500/30",
 20→  done: "bg-green-500/20 text-green-400 border-green-500/30",
 21→};
 22→
 23→const STATUS_LABELS: Record<TaskStatus, string> = {
 24→  icebox: "icebox",
 25→  todo: "todo",
 26→  "in-progress": "in progress",
 27→  done: "done",
 28→};
 29→
 30→const NEXT_STATUS: Record<TaskStatus, TaskStatus> = {
 31→  icebox: "todo",
 32→  todo: "in-progress",
 33→  "in-progress": "done",
 34→  done: "todo",
 35→};
 36→
 37→interface TaskCardProps {
 38→  task: Task;
 39→  onUpdate: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
 40→  onDelete: (taskId: string) => void;
 41→  onDelegate: (taskId: string) => void;
 42→  onSelectAgent: (agentId: string) => void;
 43→}
 44→
 45→const PRIORITIES: TaskPriority[] = ["low", "medium", "high", "urgent"];
 46→
 47→export function TaskCard({ task, onUpdate, onDelete, onDelegate, onSelectAgent }: TaskCardProps) {
 48→  const [editing, setEditing] = useState(false);
 49→  const [editTitle, setEditTitle] = useState(task.title);
 50→  const [editDesc, setEditDesc] = useState(task.description);
 51→  const [editPriority, setEditPriority] = useState(task.priority);
 52→
 53→  const startEditing = () => {
 54→    setEditTitle(task.title);
 55→    setEditDesc(task.description);
 56→    setEditPriority(task.priority);
 57→    setEditing(true);
 58→  };
 59→
 60→  const handleSaveEdit = () => {
 61→    if (!editTitle.trim()) return;
 62→    onUpdate(task.id, { title: editTitle.trim(), description: editDesc.trim(), priority: editPriority });
 63→    setEditing(false);
 64→  };
 65→
 66→  const handleCancelEdit = () => {
 67→    setEditTitle(task.title);
 68→    setEditDesc(task.description);
 69→    setEditPriority(task.priority);
 70→    setEditing(false);
 71→  };
 72→
 73→  return (
 74→    <div className="group rounded-md border bg-card p-3 text-xs">
 75→      <div className="flex items-start justify-between gap-2">
 76→        <div className="flex items-center gap-1.5 min-w-0">
 77→          <span
 78→            className={cn("shrink-0 rounded px-1.5 py-0.5 text-[10px] font-medium border", PRIORITY_COLORS[task.priority])}
 79→          >
 80→            {task.priority}
 81→          </span>
 82→          {editing ? (
 83→            <input
 84→              className="min-w-0 flex-1 bg-transparent font-medium outline-none border-b border-primary"
 85→              value={editTitle}
 86→              onChange={(e) => setEditTitle(e.target.value)}
 87→              onKeyDown={(e) => {
 88→                if (e.key === "Enter") handleSaveEdit();
 89→                if (e.key === "Escape") handleCancelEdit();
 90→              }}
 91→              autoFocus
 92→            />
 93→          ) : (
 94→            <span
 95→              className={cn(
 96→                "truncate font-medium cursor-pointer",
 97→                task.status === "done" && "line-through text-muted-foreground"
 98→              )}
 99→              onDoubleClick={startEditing}
100→            >
101→              {task.title}
102→            </span>
103→          )}
104→        </div>
105→        <div className="flex shrink-0 items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
106→          {!task.agentId && task.status !== "done" && (
107→            <Button
108→              variant="ghost"
109→              size="icon-xs"
110→              onClick={() => onDelegate(task.id)}
111→              title="Delegate to agent"
112→            >
113→              <Play className="size-3" />
114→            </Button>
115→          )}
116→          <Button
117→            variant="ghost"
118→            size="icon-xs"
119→            onClick={startEditing}
120→            title="Edit task"
121→          >
122→            <Pencil className="size-3" />
123→          </Button>
124→          <Button
125→            variant="ghost"
126→            size="icon-xs"
127→            onClick={() => onDelete(task.id)}
128→            title="Delete task"
129→          >
130→            <Trash2 className="size-3" />
131→          </Button>
132→        </div>
133→      </div>
134→
135→      {editing ? (
