  3→/**
  4→ * Right-side drawer panel that collects all file diffs from the active
  5→ * agent session into a single scrollable view, grouped by file path.
  6→ *
  7→ * ## Architecture
  8→ *
  9→ * Follows the same pattern as {@link TaskPanel} in `kanban-board.tsx`:
 10→ * - Toggled via a button in the {@link StatusBar} (GitCompareArrows icon)
 11→ * - State lives in `app/dashboard/page.tsx` (`showDiffs` boolean)
 12→ * - Rendered as a fixed right-side drawer (w-96) with mobile backdrop
 13→ * - Props threaded: page → Chat → StatusBar for the toggle button
 14→ *
 15→ * ## Data flow
 16→ *
 17→ * The panel receives `activeMessages` (the current agent's processed
 18→ * chat messages) from the page component. It derives the diff list
 19→ * via `useMemo` — no WebSocket hook changes or server-side support
 20→ * is needed. The diff data is already on each `ChatMessage.toolCalls`
 21→ * entry as `ToolCallInfo.input`.
 22→ *
 23→ * ```
 24→ * activeMessages → groupByFile() → FileGroup[] → FileGroupItem → DiffViewer
 25→ * ```
 26→ *
 27→ * ## Grouping
 28→ *
 29→ * Diffs are grouped by absolute file path using insertion order (Map).
 30→ * Multiple edits to the same file appear under one collapsible section,
 31→ * each rendered as a separate {@link DiffViewer}. This lets you see the
 32→ * full edit history for a file in chronological order.
 33→ */
 34→
 35→import { useMemo, useState } from "react";
 36→import { ChevronRight, X } from "lucide-react";
 37→import { Button } from "@/components/ui/button";
 38→import { DiffViewer } from "./diff-viewer";
 39→import { cn } from "@/lib/utils";
 40→import type { ChatMessage, ToolCallInfo } from "@/lib/types";
 41→
 42→/** Tool names whose inputs contain diff data (file_path + old/new strings). */
 43→const DIFF_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);
 44→
 45→/** A group of diffs for a single file path. */
 46→interface FileGroup {
 47→  filePath: string;
 48→  diffs: ToolCallInfo[];
 49→}
 50→
 51→/**
 52→ * Walk all messages and collect file-modifying tool calls, grouped by
 53→ * file path. Preserves insertion order so files appear in the order
 54→ * they were first touched.
 55→ */
 56→function groupByFile(messages: ChatMessage[]): FileGroup[] {
 57→  const map = new Map<string, ToolCallInfo[]>();
 58→  for (const msg of messages) {
 59→    for (const tc of msg.toolCalls ?? []) {
 60→      if (!tc.input || !DIFF_TOOLS.has(tc.name)) continue;
 61→      const filePath = String(tc.input.file_path ?? "");
 62→      if (!filePath) continue;
 63→      let group = map.get(filePath);
 64→      if (!group) {
 65→        group = [];
 66→        map.set(filePath, group);
 67→      }
 68→      group.push(tc);
 69→    }
 70→  }
 71→  return Array.from(map, ([filePath, diffs]) => ({ filePath, diffs }));
 72→}
 73→
 74→/** Collapsible section for a single file's diffs. Expanded by default. */
 75→function FileGroupItem({ group, onComment }: { group: FileGroup; onComment?: (message: string) => void }) {
 76→  const [expanded, setExpanded] = useState(true);
 77→  const basename = group.filePath.split("/").pop() ?? group.filePath;
 78→
 79→  return (
 80→    <div className="border-b border-border last:border-b-0">
 81→      <button
 82→        onClick={() => setExpanded((v) => !v)}
 83→        className="flex w-full items-center gap-2 px-3 py-2 text-xs hover:bg-muted/50 transition-colors"
 84→      >
 85→        <ChevronRight
 86→          className={cn(
 87→            "size-3 shrink-0 transition-transform",
 88→            expanded && "rotate-90"
 89→          )}
 90→        />
 91→        <span className="font-mono font-medium truncate">{basename}</span>
 92→        <span className="text-muted-foreground/60 ml-auto shrink-0">
 93→          {group.diffs.length} {group.diffs.length === 1 ? "edit" : "edits"}
 94→        </span>
 95→      </button>
 96→      {expanded && (
 97→        <div className="px-2 pb-2 space-y-2">
 98→          {group.diffs.map((tc, i) => (
 99→            <DiffViewer key={tc.toolUseId ?? i} toolCall={tc} onComment={onComment} />
100→          ))}
101→        </div>
102→      )}
103→    </div>
104→  );
105→}
106→
107→/**
108→ * Sidebar panel listing all file diffs from the current agent session.
109→ *
110→ * @param messages — The active agent's `ChatMessage[]` from `useWebSocket`.
111→ *   File-modifying tool calls are extracted and grouped by file path.
112→ * @param onSendMessage — Callback to send a comment to the active session.
113→ * @param onClose — Callback to hide the panel (sets `showDiffs` to false).
114→ */
115→export function DiffsPanel({
116→  messages,
117→  onSendMessage,
118→  onClose,
119→}: {
120→  messages: ChatMessage[];
121→  onSendMessage?: (content: string) => void;
122→  onClose: () => void;
123→}) {
124→  const fileGroups = useMemo(() => groupByFile(messages), [messages]);
125→  const totalDiffs = fileGroups.reduce((sum, g) => sum + g.diffs.length, 0);
126→
127→  return (
128→    <div className="flex h-full min-w-0 flex-col overflow-hidden">
129→      {/* Header */}
130→      <div className="flex items-center justify-between border-b px-3 py-2">
131→        <div className="flex items-center gap-2">
132→          <span className="text-xs font-semibold">Diffs</span>
133→          {totalDiffs > 0 && (
134→            <span className="rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-mono text-muted-foreground">
135→              {totalDiffs}
136→            </span>
137→          )}
138→        </div>
139→        <Button variant="ghost" size="icon-xs" onClick={onClose} title="Close">
140→          <X className="size-3.5" />
141→        </Button>
142→      </div>
143→
144→      {/* Content */}
145→      <div className="flex-1 overflow-y-auto">
146→        {fileGroups.length === 0 ? (
147→          <div className="flex h-full items-center justify-center text-xs text-muted-foreground">
148→            No file changes yet
149→          </div>
150→        ) : (
151→          fileGroups.map((group) => (
152→            <FileGroupItem key={group.filePath} group={group} onComment={onSendMessage} />
153→          ))
154→        )}
155→      </div>
156→    </div>
157→  );
158→}
