  3→/**
  4→ * Modal dialog for browsing the server's filesystem and selecting a
  5→ * directory to create a new workspace.
  6→ *
  7→ * Uses the `browse_directory` WebSocket message to fetch directory
  8→ * listings from the server (works over Tailscale).
  9→ */
 10→
 11→import { useCallback, useEffect, useState } from "react";
 12→import { Folder, FolderUp, X } from "lucide-react";
 13→import type { DirectoryEntry } from "@/lib/types";
 14→import { cn } from "@/lib/utils";
 15→
 16→export function FolderBrowser({
 17→  open,
 18→  onClose,
 19→  directoryListing,
 20→  onBrowse,
 21→  onCreate,
 22→  initialPath,
 23→}: {
 24→  open: boolean;
 25→  onClose: () => void;
 26→  directoryListing: { path: string; entries: DirectoryEntry[] } | null;
 27→  onBrowse: (path: string) => void;
 28→  onCreate: (name: string, cwd: string) => void;
 29→  /** Starting directory path (defaults to server cwd). */
 30→  initialPath: string;
 31→}) {
 32→  const [name, setName] = useState("");
 33→  const [selectedPath, setSelectedPath] = useState(initialPath);
 34→
 35→  // Browse initial path on open
 36→  useEffect(() => {
 37→    if (open) {
 38→      setSelectedPath(initialPath);
 39→      setName(getBasename(initialPath));
 40→      onBrowse(initialPath);
 41→    }
 42→    // eslint-disable-next-line react-hooks/exhaustive-deps
 43→  }, [open]);
 44→
 45→  // Update name when browsing to a new directory
 46→  useEffect(() => {
 47→    if (directoryListing) {
 48→      setSelectedPath(directoryListing.path);
 49→      setName(getBasename(directoryListing.path));
 50→    }
 51→  }, [directoryListing]);
 52→
 53→  const navigateTo = useCallback(
 54→    (path: string) => {
 55→      onBrowse(path);
 56→    },
 57→    [onBrowse]
 58→  );
 59→
 60→  const handleCreate = useCallback(() => {
 61→    const trimmed = name.trim();
 62→    if (!trimmed || !selectedPath) return;
 63→    onCreate(trimmed, selectedPath);
 64→    onClose();
 65→  }, [name, selectedPath, onCreate, onClose]);
 66→
 67→  // Close on Escape
 68→  useEffect(() => {
 69→    if (!open) return;
 70→    function handleKey(e: KeyboardEvent) {
 71→      if (e.key === "Escape") onClose();
 72→    }
 73→    document.addEventListener("keydown", handleKey);
 74→    return () => document.removeEventListener("keydown", handleKey);
 75→  }, [open, onClose]);
 76→
 77→  if (!open) return null;
 78→
 79→  const currentPath = directoryListing?.path ?? selectedPath;
 80→  const entries = directoryListing?.entries ?? [];
 81→  const pathParts = currentPath.split("/").filter(Boolean);
 82→
 83→  return (
 84→    <>
 85→      {/* Modal overlay + backdrop */}
 86→      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4" onClick={onClose}>
 87→        <div
 88→          className="w-full max-w-lg rounded-lg border bg-background shadow-lg flex flex-col max-h-[80vh]"
 89→          onClick={(e) => e.stopPropagation()}
 90→        >
 91→          {/* Header */}
 92→          <div className="flex items-center justify-between border-b px-4 py-3">
 93→            <h2 className="text-sm font-semibold">Open Folder</h2>
 94→            <button
 95→              onClick={onClose}
 96→              className="rounded p-1 hover:bg-accent transition-colors"
 97→              aria-label="Close"
 98→            >
 99→              <X className="size-4" />
100→            </button>
101→          </div>
102→
103→          {/* Breadcrumb */}
104→          <div className="flex items-center gap-1 border-b px-4 py-2 text-xs text-muted-foreground overflow-x-auto">
105→            <button
106→              onClick={() => navigateTo("/")}
107→              className="shrink-0 hover:text-foreground transition-colors"
108→            >
109→              /
110→            </button>
111→            {pathParts.map((part, i) => {
112→              const fullPath = "/" + pathParts.slice(0, i + 1).join("/");
113→              const isLast = i === pathParts.length - 1;
114→              return (
115→                <span key={fullPath} className="flex items-center gap-1">
116→                  <span className="text-muted-foreground/50">/</span>
117→                  <button
118→                    onClick={() => navigateTo(fullPath)}
119→                    className={cn(
120→                      "shrink-0 transition-colors",
121→                      isLast ? "text-foreground font-medium" : "hover:text-foreground"
122→                    )}
123→                  >
124→                    {part}
125→                  </button>
126→                </span>
127→              );
128→            })}
129→          </div>
130→
131→          {/* Directory listing */}
132→          <div className="flex-1 overflow-y-auto min-h-0">
133→            {entries.length === 0 ? (
134→              <div className="px-4 py-8 text-center text-xs text-muted-foreground">
135→                Empty directory
136→              </div>
137→            ) : (
138→              <div className="py-1">
139→                {entries.map((entry) => (
140→                  <button
141→                    key={entry.path}
142→                    onClick={() => navigateTo(entry.path)}
143→                    className="flex w-full items-center gap-2 px-4 py-1.5 text-xs transition-colors hover:bg-accent text-left"
144→                  >
145→                    {entry.name === ".." ? (
146→                      <FolderUp className="size-4 shrink-0 text-muted-foreground" />
147→                    ) : (
148→                      <Folder className="size-4 shrink-0 text-muted-foreground" />
149→                    )}
150→                    <span className="truncate">{entry.name}</span>
151→                  </button>
152→                ))}
153→              </div>
154→            )}
155→          </div>
156→
157→          {/* Footer: name input + open button */}
158→          <div className="border-t px-4 py-3 flex items-center gap-2">
159→            <input
160→              type="text"
161→              value={name}
162→              onChange={(e) => setName(e.target.value)}
163→              onKeyDown={(e) => {
164→                if (e.key === "Enter") handleCreate();
165→              }}
166→              placeholder="Workspace name"
167→              className="flex-1 rounded border bg-background px-2 py-1.5 text-xs outline-none focus:ring-1 focus:ring-ring"
168→            />
169→            <button
170→              onClick={handleCreate}
171→              disabled={!name.trim()}
172→              className="rounded-md bg-primary px-3 py-1.5 text-xs font-medium text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-50"
173→            >
174→              Open
175→            </button>
176→          </div>
177→        </div>
178→      </div>
179→    </>
180→  );
181→}
