 10→  sfxPreview,
 11→  type SfxSettings,
 12→  type SfxCategoryKey,
 13→} from "@/lib/sfx";
 14→import { cn } from "@/lib/utils";
 15→
 16→export function SfxSettings({ open, onClose }: { open: boolean; onClose: () => void }) {
 17→  const [settings, setSettings] = useState<SfxSettings>(getSfxSettings);
 18→
 19→  // Sync from module on open
 20→  useEffect(() => {
 21→    if (open) setSettings(getSfxSettings());
 22→  }, [open]);
 23→
 24→  const update = useCallback((next: SfxSettings) => {
 25→    setSettings(next);
 26→    setSfxSettings(next);
 27→  }, []);
 28→
 29→  const setMaster = useCallback((v: number) => {
 30→    update({ ...settings, master: v });
 31→  }, [settings, update]);
 32→
 33→  const toggleMute = useCallback(() => {
 34→    update({ ...settings, muted: !settings.muted });
 35→  }, [settings, update]);
 36→
 37→  const setCatVolume = useCallback((key: SfxCategoryKey, v: number) => {
 38→    update({
 39→      ...settings,
 40→      categories: {
 41→        ...settings.categories,
 42→        [key]: { ...settings.categories[key], volume: v },
 43→      },
 44→    });
 45→  }, [settings, update]);
 46→
 47→  const toggleCat = useCallback((key: SfxCategoryKey) => {
 48→    update({
 49→      ...settings,
 50→      categories: {
 51→        ...settings.categories,
 52→        [key]: { ...settings.categories[key], enabled: !settings.categories[key].enabled },
 53→      },
 54→    });
 55→  }, [settings, update]);
 56→
 57→  useEffect(() => {
 58→    if (!open) return;
 59→    const onKeyDown = (e: KeyboardEvent) => {
 60→      if (e.key === "Escape") onClose();
 61→    };
 62→    window.addEventListener("keydown", onKeyDown);
 63→    return () => window.removeEventListener("keydown", onKeyDown);
 64→  }, [open, onClose]);
 65→
 66→  if (!open) return null;
 67→
 68→  return (
 69→    <div
 70→      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
 71→      onClick={onClose}
 72→    >
 73→      <div
 74→        className="w-full max-w-md rounded-lg border bg-background shadow-lg flex flex-col max-h-[80vh]"
 75→        onClick={(e) => e.stopPropagation()}
 76→      >
 77→        {/* Header */}
 78→        <div className="flex items-center justify-between border-b px-4 py-3">
 79→          <h2 className="text-sm font-semibold flex items-center gap-2">
 80→            <Volume2 className="size-4" />
 81→            Sound Effects
 82→          </h2>
 83→          <button
 84→            onClick={onClose}
 85→            className="rounded p-1 transition-colors hover:bg-muted/50"
 86→          >
 87→            <X className="size-4" />
 88→          </button>
 89→        </div>
 90→
 91→        {/* Content */}
 92→        <div className="flex-1 overflow-y-auto min-h-0 px-4 py-3 space-y-4">
 93→          {/* Master volume */}
 94→          <div className="flex items-center gap-3">
 95→            <span className="text-xs text-muted-foreground w-20 shrink-0">Master</span>
 96→            <input
 97→              type="range"
 98→              min={0}
 99→              max={100}
100→              value={Math.round(settings.master * 100)}
101→              onChange={(e) => setMaster(Number(e.target.value) / 100)}
102→              className="flex-1 h-1.5 accent-primary cursor-pointer"
103→            />
104→            <span className="text-xs text-muted-foreground w-8 text-right tabular-nums">
105→              {Math.round(settings.master * 100)}
106→            </span>
107→            <Button
108→              variant={settings.muted ? "destructive" : "ghost"}
109→              size="icon-xs"
110→              onClick={toggleMute}
111→              title={settings.muted ? "Unmute all" : "Mute all"}
112→            >
113→              {settings.muted ? <VolumeX className="size-3.5" /> : <Volume2 className="size-3.5" />}
114→            </Button>
115→          </div>
116→
117→          {/* Divider */}
118→          <div className="border-t" />
119→
120→          {/* Category rows */}
121→          <div className="space-y-2.5">
122→            {SFX_CATEGORIES.map((cat) => {
123→              const catSettings = settings.categories[cat.key];
124→              const disabled = settings.muted || !catSettings.enabled;
125→              return (
126→                <div key={cat.key} className={cn("space-y-1", disabled && "opacity-40")}>
127→                  {/* Row 1: label + controls */}
128→                  <div className="flex items-center gap-2">
129→                    {/* Color dot */}
130→                    <span className={cn("size-2 rounded-full shrink-0", cat.color)} />
131→                    {/* Label */}
