"use client";

/**
 * Right-side drawer panel that collects all file diffs from the active
 * agent session into a single scrollable view, grouped by file path.
 *
 * ## Architecture
 *
 * Follows the same pattern as {@link TaskPanel} in `kanban-board.tsx`:
 * - Toggled via a button in the {@link StatusBar} (GitCompareArrows icon)
 * - State lives in `app/dashboard/page.tsx` (`showDiffs` boolean)
 * - Rendered as a fixed right-side drawer (w-96) with mobile backdrop
 * - Props threaded: page → Chat → StatusBar for the toggle button
 *
 * ## Data flow
 *
 * The panel receives `activeMessages` (the current agent's processed
 * chat messages) from the page component. It derives the diff list
 * via `useMemo` — no WebSocket hook changes or server-side support
 * is needed. The diff data is already on each `ChatMessage.toolCalls`
 * entry as `ToolCallInfo.input`.
 *
 * ```
 * activeMessages → groupByFile() → FileGroup[] → FileGroupItem → DiffViewer
 * ```
 *
 * ## Grouping
 *
 * Diffs are grouped by absolute file path using insertion order (Map).
 * Multiple edits to the same file appear under one collapsible section,
 * each rendered as a separate {@link DiffViewer}. This lets you see the
 * full edit history for a file in chronological order.
 */

import { useMemo, useState } from "react";
import { ChevronRight, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { DiffViewer } from "./diff-viewer";
import { cn } from "@/lib/utils";
import type { ChatMessage, ToolCallInfo } from "@/lib/types";

/** Tool names whose inputs contain diff data (file_path + old/new strings). */
const DIFF_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);

/** A group of diffs for a single file path. */
interface FileGroup {
  filePath: string;
  diffs: ToolCallInfo[];
}

/**
 * Walk all messages and collect file-modifying tool calls, grouped by
 * file path. Preserves insertion order so files appear in the order
 * they were first touched.
 */
function groupByFile(messages: ChatMessage[]): FileGroup[] {
  const map = new Map<string, ToolCallInfo[]>();
  for (const msg of messages) {
    for (const tc of msg.toolCalls ?? []) {
      if (!tc.input || !DIFF_TOOLS.has(tc.name)) continue;
      const filePath = String(tc.input.file_path ?? "");
      if (!filePath) continue;
      let group = map.get(filePath);
      if (!group) {
        group = [];
        map.set(filePath, group);
      }
      group.push(tc);
    }
  }
  return Array.from(map, ([filePath, diffs]) => ({ filePath, diffs }));
}

/** Collapsible section for a single file's diffs. Expanded by default. */
function FileGroupItem({ group, onComment }: { group: FileGroup; onComment?: (message: string) => void }) {
  const [expanded, setExpanded] = useState(true);
  const basename = group.filePath.split("/").pop() ?? group.filePath;

  return (
    <div className="border-b border-border last:border-b-0">
      <button
        onClick={() => setExpanded((v) => !v)}
        className="flex w-full items-center gap-2 px-3 py-2 text-xs hover:bg-muted/50 transition-colors"
      >
        <ChevronRight
          className={cn(
            "size-3 shrink-0 transition-transform",
            expanded && "rotate-90"
          )}
        />
        <span className="font-mono font-medium truncate">{basename}</span>
        <span className="text-muted-foreground/60 ml-auto shrink-0">
          {group.diffs.length} {group.diffs.length === 1 ? "edit" : "edits"}
        </span>
      </button>
      {expanded && (
        <div className="px-2 pb-2 space-y-2">
          {group.diffs.map((tc, i) => (
            <DiffViewer key={tc.toolUseId ?? i} toolCall={tc} onComment={onComment} />
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * Sidebar panel listing all file diffs from the current agent session.
 *
 * @param messages — The active agent's `ChatMessage[]` from `useWebSocket`.
 *   File-modifying tool calls are extracted and grouped by file path.
 * @param onSendMessage — Callback to send a comment to the active session.
 * @param onClose — Callback to hide the panel (sets `showDiffs` to false).
 */
export function DiffsPanel({
  messages,
  onSendMessage,
  onClose,
}: {
  messages: ChatMessage[];
  onSendMessage?: (content: string) => void;
  onClose: () => void;
}) {
  const fileGroups = useMemo(() => groupByFile(messages), [messages]);
  const totalDiffs = fileGroups.reduce((sum, g) => sum + g.diffs.length, 0);

  return (
    <div className="flex h-full min-w-0 flex-col overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between border-b px-3 py-2">
        <div className="flex items-center gap-2">
          <span className="text-xs font-semibold">Diffs</span>
          {totalDiffs > 0 && (
            <span className="rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-mono text-muted-foreground">
              {totalDiffs}
            </span>
          )}
        </div>
        <Button variant="ghost" size="icon-xs" onClick={onClose} title="Close">
          <X className="size-3.5" />
        </Button>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto">
        {fileGroups.length === 0 ? (
          <div className="flex h-full items-center justify-center text-xs text-muted-foreground">
            No file changes yet
          </div>
        ) : (
          fileGroups.map((group) => (
            <FileGroupItem key={group.filePath} group={group} onComment={onSendMessage} />
          ))
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * Modal dialog for browsing the server's filesystem and selecting a
 * directory to create a new workspace.
 *
 * Uses the `browse_directory` WebSocket message to fetch directory
 * listings from the server (works over Tailscale).
 */

import { useCallback, useEffect, useState } from "react";
import { Folder, FolderUp, X } from "lucide-react";
import type { DirectoryEntry } from "@/lib/types";
import { cn } from "@/lib/utils";

export function FolderBrowser({
  open,
  onClose,
  directoryListing,
  onBrowse,
  onCreate,
  initialPath,
}: {
  open: boolean;
  onClose: () => void;
  directoryListing: { path: string; entries: DirectoryEntry[] } | null;
  onBrowse: (path: string) => void;
  onCreate: (name: string, cwd: string) => void;
  /** Starting directory path (defaults to server cwd). */
  initialPath: string;
}) {
  const [name, setName] = useState("");
  const [selectedPath, setSelectedPath] = useState(initialPath);

  // Browse initial path on open
  useEffect(() => {
    if (open) {
      setSelectedPath(initialPath);
      setName(getBasename(initialPath));
      onBrowse(initialPath);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  // Update name when browsing to a new directory
  useEffect(() => {
    if (directoryListing) {
      setSelectedPath(directoryListing.path);
      setName(getBasename(directoryListing.path));
    }
  }, [directoryListing]);

  const navigateTo = useCallback(
    (path: string) => {
      onBrowse(path);
    },
    [onBrowse]
  );

  const handleCreate = useCallback(() => {
    const trimmed = name.trim();
    if (!trimmed || !selectedPath) return;
    onCreate(trimmed, selectedPath);
    onClose();
  }, [name, selectedPath, onCreate, onClose]);

  // Close on Escape
  useEffect(() => {
    if (!open) return;
    function handleKey(e: KeyboardEvent) {
      if (e.key === "Escape") onClose();
    }
    document.addEventListener("keydown", handleKey);
    return () => document.removeEventListener("keydown", handleKey);
  }, [open, onClose]);

  if (!open) return null;

  const currentPath = directoryListing?.path ?? selectedPath;
  const entries = directoryListing?.entries ?? [];
  const pathParts = currentPath.split("/").filter(Boolean);

  return (
    <>
      {/* Modal overlay + backdrop */}
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4" onClick={onClose}>
        <div
          className="w-full max-w-lg rounded-lg border bg-background shadow-lg flex flex-col max-h-[80vh]"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Header */}
          <div className="flex items-center justify-between border-b px-4 py-3">
            <h2 className="text-sm font-semibold">Open Folder</h2>
            <button
              onClick={onClose}
              className="rounded p-1 hover:bg-accent transition-colors"
              aria-label="Close"
            >
              <X className="size-4" />
            </button>
          </div>

          {/* Breadcrumb */}
          <div className="flex items-center gap-1 border-b px-4 py-2 text-xs text-muted-foreground overflow-x-auto">
            <button
              onClick={() => navigateTo("/")}
              className="shrink-0 hover:text-foreground transition-colors"
            >
              /
            </button>
            {pathParts.map((part, i) => {
              const fullPath = "/" + pathParts.slice(0, i + 1).join("/");
              const isLast = i === pathParts.length - 1;
              return (
                <span key={fullPath} className="flex items-center gap-1">
                  <span className="text-muted-foreground/50">/</span>
                  <button
                    onClick={() => navigateTo(fullPath)}
                    className={cn(
                      "shrink-0 transition-colors",
                      isLast ? "text-foreground font-medium" : "hover:text-foreground"
                    )}
                  >
                    {part}
                  </button>
                </span>
              );
            })}
          </div>

          {/* Directory listing */}
          <div className="flex-1 overflow-y-auto min-h-0">
            {entries.length === 0 ? (
              <div className="px-4 py-8 text-center text-xs text-muted-foreground">
                Empty directory
              </div>
            ) : (
              <div className="py-1">
                {entries.map((entry) => (
                  <button
                    key={entry.path}
                    onClick={() => navigateTo(entry.path)}
                    className="flex w-full items-center gap-2 px-4 py-1.5 text-xs transition-colors hover:bg-accent text-left"
                  >
                    {entry.name === ".." ? (
                      <FolderUp className="size-4 shrink-0 text-muted-foreground" />
                    ) : (
                      <Folder className="size-4 shrink-0 text-muted-foreground" />
                    )}
                    <span className="truncate">{entry.name}</span>
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Footer: name input + open button */}
          <div className="border-t px-4 py-3 flex items-center gap-2">
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") handleCreate();
              }}
              placeholder="Workspace name"
              className="flex-1 rounded border bg-background px-2 py-1.5 text-xs outline-none focus:ring-1 focus:ring-ring"
            />
            <button
              onClick={handleCreate}
              disabled={!name.trim()}
              className="rounded-md bg-primary px-3 py-1.5 text-xs font-medium text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-50"
            >
              Open
            </button>
          </div>
        </div>
      </div>
    </>
  );
}

/** Extract the last segment of a path for use as default workspace name. */
function getBasename(path: string): string {
  const parts = path.split("/").filter(Boolean);
  return parts.length > 0 ? parts[parts.length - 1] : "";
}

"use client";

/**
 * Sidebar listing all agents with status dots, truncated labels,
 * tmux session names, and a "+" button to spawn a new agent.
 *
 * Split into two sections:
 * - **Active**: agents with status `spawning`, `connected`, or `thinking`.
 * - **Archived**: agents with status `done`, `disconnected`, or `error` (read-only).
 *
 * Right-click (or kebab icon) context menu supports: Rename, Kill, Clear History, Delete.
 * Rename swaps the label for an inline input.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { EllipsisVertical, Pin, Snowflake, Plus } from "lucide-react";
import type { AgentStatus, Workspace } from "@/lib/types";
import type { AgentClientState } from "@/hooks/use-websocket";
import { cn } from "@/lib/utils";
import { WorkspaceSwitcher } from "./workspace-switcher";

/** Status dot color + optional pulse animation. */
const STATUS_DOT: Record<AgentStatus, string> = {
  idle: "bg-muted-foreground",
  spawning: "bg-yellow-500 animate-pulse",
  connected: "bg-green-500",
  thinking: "bg-blue-500 animate-pulse",
  done: "bg-muted-foreground",
  disconnected: "bg-orange-500 animate-pulse",
  error: "bg-red-500",
};

/** Statuses where the CLI is actively running and can be killed. */
const KILLABLE: Set<AgentStatus> = new Set(["spawning", "connected", "thinking"]);
/** Statuses considered archived (session ended, read-only). */
const ARCHIVED: Set<AgentStatus> = new Set(["done", "disconnected", "error"]);

interface ContextMenuState {
  agentId: string;
  x: number;
  y: number;
}

export function AgentSidebar({
  agents,
  agentOrder,
  activeAgentId,
  loading,
  onSelect,
  onNewAgent,
  onKill,
  onDelete,
  onRename,
  onClearHistory,
  onPin,
  onIcebox,
  workspaces,
  activeWorkspaceId,
  onSelectWorkspace,
  onRenameWorkspace,
  onDeleteWorkspace,
  onOpenFolder,
}: {
  agents: Map<string, AgentClientState>;
  agentOrder: string[];
  activeAgentId: string | null;
  loading?: boolean;
  onSelect: (agentId: string | null) => void;
  onNewAgent: () => void;
  onKill: (agentId: string) => void;
  onDelete: (agentId: string) => void;
  onRename: (agentId: string, label: string) => void;
  onClearHistory: (agentId: string) => void;
  onPin: (agentId: string, pinned: boolean) => void;
  onIcebox: (agentId: string, iceboxed: boolean) => void;
  workspaces: Workspace[];
  activeWorkspaceId: string | null;
