          )}
        </div>
      </div>
    </div>
  );
}

"use client";

/**
 * Top bar showing the WS connection state (green/red dot), the current
 * agent lifecycle status, active model name, and a model selector dropdown.
 */

import { useEffect, useRef, useState } from "react";
import { ChevronDown, GitCompareArrows, ListTodo, Menu, Volume2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Tip } from "@/components/ui/tip";
import { cn } from "@/lib/utils";
import type { AgentStatus } from "@/lib/types";

/** Human-readable labels for each agent status. */
const STATUS_LABELS: Record<AgentStatus, string> = {
  idle: "idle",
  spawning: "spawning...",
  connected: "connected",
  thinking: "thinking...",
  done: "done",
  disconnected: "disconnected",
  error: "error",
};

/** Curated list of common models for the dropdown. */
const MODEL_PRESETS = [
  { value: "", label: "Default (CLI)", description: "Use CLI default model" },
  { value: "claude-sonnet-4-20250514", label: "Sonnet 4", description: "Claude Sonnet 4" },
  { value: "claude-opus-4-20250514", label: "Opus 4", description: "Claude Opus 4" },
  { value: "qwen3-coder", label: "Qwen3 Coder", description: "Ollama — Qwen3 Coder" },
  { value: "devstral", label: "Devstral", description: "Ollama — Devstral" },
];

export function StatusBar({
  connected,
  status,
  agentLabel,
  activeModel,
  selectedModel,
  onModelChange,
  showRaw,
  onToggleRaw,
  showTasks,
  onToggleTasks,
  showDiffs,
  onToggleDiffs,
  onToggleSidebar,
  onOpenSfxSettings,
}: {
  connected: boolean;
  status: AgentStatus;
  agentLabel?: string | null;
  activeModel?: string | null;
  selectedModel?: string;
  onModelChange?: (model: string) => void;
  showRaw?: boolean;
  onToggleRaw?: () => void;
  showTasks?: boolean;
  onToggleTasks?: () => void;
  showDiffs?: boolean;
  onToggleDiffs?: () => void;
  onToggleSidebar?: () => void;
  onOpenSfxSettings?: () => void;
}) {
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [customInput, setCustomInput] = useState("");
  const [showCustom, setShowCustom] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const customInputRef = useRef<HTMLInputElement>(null);

  // Close dropdown on click-outside or Escape
  useEffect(() => {
    if (!dropdownOpen) return;
    function handleClick(e: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setDropdownOpen(false);
        setShowCustom(false);
      }
    }
    function handleKey(e: KeyboardEvent) {
      if (e.key === "Escape") {
        setDropdownOpen(false);
        setShowCustom(false);
      }
    }
    document.addEventListener("mousedown", handleClick);
    document.addEventListener("keydown", handleKey);
    return () => {
      document.removeEventListener("mousedown", handleClick);
      document.removeEventListener("keydown", handleKey);
    };
  }, [dropdownOpen]);

  // Focus custom input when it appears
  useEffect(() => {
    if (showCustom) customInputRef.current?.focus();
  }, [showCustom]);

  /** Shorten a model name for display (e.g. "claude-sonnet-4-20250514" → "sonnet-4"). */
  function shortModel(model: string): string {
    // Match known preset labels
    const preset = MODEL_PRESETS.find((p) => p.value === model);
    if (preset && preset.value) return preset.label;
    // Strip "claude-" prefix and date suffix for Claude models
    const m = model.replace(/^claude-/, "").replace(/-\d{8}$/, "");
    return m || model;
  }

  const displayModel = activeModel ?? (selectedModel || null);
  const isActive = status === "connected" || status === "thinking";

  return (
    <div className="flex items-center justify-between border-b px-2 py-2 text-xs md:px-4">
      {/* Left side */}
      <div className="flex items-center gap-2">
        {onToggleSidebar && (
          <button
            onClick={onToggleSidebar}
            className="rounded p-1 transition-colors hover:bg-muted/50 md:hidden"
            aria-label="Toggle sidebar"
          >
            <Menu className="size-4" />
          </button>
        )}
        <span className="text-muted-foreground font-semibold hidden md:inline">thos dashboard</span>
        <span className="text-muted-foreground font-semibold md:hidden">thos</span>
        {agentLabel && (
          <>
            <span className="text-muted-foreground/50">/</span>
            <span className="truncate max-w-[150px] md:max-w-[250px] font-medium text-foreground/80" title={agentLabel}>{agentLabel}</span>
          </>
        )}
      </div>

      {/* Right side */}
      <div className="flex items-center gap-1.5 md:gap-3">
        <span className="flex items-center gap-1.5">
          <span
            className={`inline-block size-2 rounded-full ${
              connected ? "bg-green-500" : "bg-red-500"
            }`}
          />
          <span className="hidden md:inline">
            {connected ? "ws connected" : "ws disconnected"}
          </span>
        </span>
        <span className="text-muted-foreground hidden md:inline">|</span>
        <span className="hidden md:inline">agent: {STATUS_LABELS[status]}</span>
        <span className="text-[10px] md:hidden">{STATUS_LABELS[status]}</span>

        {/* Model display + selector */}
        {onModelChange && (
          <>
            <span className="text-muted-foreground hidden md:inline">|</span>
            <div className="relative" ref={dropdownRef}>
              <button
                onClick={() => setDropdownOpen((v) => !v)}
                className={cn(
                  "flex items-center gap-1 rounded px-1.5 py-0.5 font-mono transition-colors",
                  "hover:bg-muted/80 text-muted-foreground",
                  dropdownOpen && "bg-muted"
                )}
                title={displayModel ? `Model: ${displayModel}` : "Select model for next spawn"}
              >
                <span className="max-w-[120px] truncate text-[10px] md:text-xs md:max-w-[180px]">
                  {displayModel ? shortModel(displayModel) : "model"}
                </span>
                <ChevronDown className="size-3 shrink-0" />
              </button>

              {dropdownOpen && (
                <div className="absolute right-0 top-full z-50 mt-1 min-w-[220px] rounded-md border bg-popover p-1 shadow-md">
                  {isActive && activeModel && (
                    <div className="px-2 py-1.5 text-[10px] text-muted-foreground border-b mb-1">
                      Active: <span className="font-mono">{activeModel}</span>
                    </div>
                  )}
                  <div className="px-2 py-1 text-[10px] text-muted-foreground uppercase tracking-wider">
                    Next spawn
                  </div>
                  {MODEL_PRESETS.map((preset) => (
                    <button
                      key={preset.value}
                      onClick={() => {
                        onModelChange(preset.value);
                        setDropdownOpen(false);
                        setShowCustom(false);
                      }}
                      className={cn(
                        "flex w-full flex-col rounded px-2 py-1.5 text-left transition-colors hover:bg-accent",
                        selectedModel === preset.value && "bg-accent"
                      )}
                    >
                      <span className="text-xs font-medium">{preset.label}</span>
                      <span className="text-[10px] text-muted-foreground">{preset.description}</span>
                    </button>
                  ))}
                  <div className="my-1 border-t" />
                  {showCustom ? (
                    <form
                      onSubmit={(e) => {
                        e.preventDefault();
                        const val = customInput.trim();
                        if (val) {
                          onModelChange(val);
                          setCustomInput("");
                          setShowCustom(false);
                          setDropdownOpen(false);
                        }
                      }}
                      className="px-2 py-1"
                    >
                      <input
                        ref={customInputRef}
                        type="text"
                        value={customInput}
                        onChange={(e) => setCustomInput(e.target.value)}
                        placeholder="e.g. llama3.3:70b"
                        className="w-full rounded border bg-background px-2 py-1 text-xs outline-none focus:ring-1 focus:ring-ring"
                      />
                    </form>
                  ) : (
                    <button
                      onClick={() => setShowCustom(true)}
                      className="flex w-full rounded px-2 py-1.5 text-left text-xs text-muted-foreground transition-colors hover:bg-accent"
                    >
                      Custom model...
                    </button>
                  )}
                </div>
              )}
            </div>
          </>
        )}

        <span className="text-muted-foreground hidden md:inline">|</span>
        <div className="flex items-center gap-1.5">
          {onToggleRaw && (
            <button
              onClick={onToggleRaw}
              className={cn(
                "rounded px-2 py-0.5 text-[10px] font-mono transition-colors",
                showRaw
                  ? "bg-foreground text-background"
                  : "bg-muted text-muted-foreground hover:bg-muted/80"
              )}
            >
              {showRaw ? "RAW" : "raw"}
            </button>
          )}
          {onToggleDiffs && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={onToggleDiffs}
              title="Toggle diffs"
              className={cn(showDiffs && "text-primary")}
            >
              <GitCompareArrows className="size-3.5" />
            </Button>
          )}
          {onToggleTasks && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={onToggleTasks}
              title="Toggle tasks"
              className={cn(showTasks && "text-primary")}
            >
              <ListTodo className="size-3.5" />
            </Button>
          )}
          {onOpenSfxSettings && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={onOpenSfxSettings}
              title="Sound settings"
            >
              <Volume2 className="size-3.5" />
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Play, Pencil, Trash2, ExternalLink, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { Task, TaskStatus, TaskPriority } from "@/lib/types";

const PRIORITY_COLORS: Record<TaskPriority, string> = {
  urgent: "bg-red-500/20 text-red-400 border-red-500/30",
  high: "bg-orange-500/20 text-orange-400 border-orange-500/30",
  medium: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
  low: "bg-muted text-muted-foreground border-border",
};

const STATUS_COLORS: Record<TaskStatus, string> = {
  icebox: "bg-purple-500/20 text-purple-400 border-purple-500/30",
  todo: "border-border text-muted-foreground",
  "in-progress": "bg-blue-500/20 text-blue-400 border-blue-500/30",
  done: "bg-green-500/20 text-green-400 border-green-500/30",
};

const STATUS_LABELS: Record<TaskStatus, string> = {
  icebox: "icebox",
  todo: "todo",
  "in-progress": "in progress",
  done: "done",
};

const NEXT_STATUS: Record<TaskStatus, TaskStatus> = {
  icebox: "todo",
  todo: "in-progress",
  "in-progress": "done",
  done: "todo",
};

interface TaskCardProps {
  task: Task;
  onUpdate: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
  onDelete: (taskId: string) => void;
  onDelegate: (taskId: string) => void;
  onSelectAgent: (agentId: string) => void;
}

const PRIORITIES: TaskPriority[] = ["low", "medium", "high", "urgent"];

export function TaskCard({ task, onUpdate, onDelete, onDelegate, onSelectAgent }: TaskCardProps) {
  const [editing, setEditing] = useState(false);
  const [editTitle, setEditTitle] = useState(task.title);
  const [editDesc, setEditDesc] = useState(task.description);
  const [editPriority, setEditPriority] = useState(task.priority);

  const startEditing = () => {
    setEditTitle(task.title);
    setEditDesc(task.description);
    setEditPriority(task.priority);
    setEditing(true);
  };

  const handleSaveEdit = () => {
    if (!editTitle.trim()) return;
    onUpdate(task.id, { title: editTitle.trim(), description: editDesc.trim(), priority: editPriority });
    setEditing(false);
  };

  const handleCancelEdit = () => {
    setEditTitle(task.title);
    setEditDesc(task.description);
    setEditPriority(task.priority);
    setEditing(false);
  };

  return (
    <div className="group rounded-md border bg-card p-3 text-xs">
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-1.5 min-w-0">
          <span
            className={cn("shrink-0 rounded px-1.5 py-0.5 text-[10px] font-medium border", PRIORITY_COLORS[task.priority])}
          >
            {task.priority}
          </span>
          {editing ? (
            <input
              className="min-w-0 flex-1 bg-transparent font-medium outline-none border-b border-primary"
              value={editTitle}
              onChange={(e) => setEditTitle(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") handleSaveEdit();
                if (e.key === "Escape") handleCancelEdit();
              }}
              autoFocus
            />
          ) : (
            <span
              className={cn(
                "truncate font-medium cursor-pointer",
                task.status === "done" && "line-through text-muted-foreground"
              )}
              onDoubleClick={startEditing}
              title={task.title}
            >
              {task.title}
            </span>
          )}
        </div>
        <div className="flex shrink-0 items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
          {!task.agentId && task.status !== "done" && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={() => onDelegate(task.id)}
              title="Delegate to agent"
            >
              <Play className="size-3" />
            </Button>
          )}
          <Button
            variant="ghost"
            size="icon-xs"
            onClick={startEditing}
            title="Edit task"
          >
            <Pencil className="size-3" />
          </Button>
          <Button
            variant="ghost"
            size="icon-xs"
            onClick={() => onDelete(task.id)}
            title="Delete task"
          >
            <Trash2 className="size-3" />
          </Button>
        </div>
      </div>

      {editing ? (
        <div className="mt-2 space-y-2">
          <textarea
            className="w-full rounded border bg-transparent p-1.5 text-xs outline-none resize-none"
            value={editDesc}
            onChange={(e) => setEditDesc(e.target.value)}
            rows={2}
            placeholder="Description..."
          />
          <div className="flex items-center gap-1">
            {PRIORITIES.map((p) => (
              <button
                key={p}
                className={cn(
                  "rounded px-1.5 py-0.5 text-[10px] font-medium border transition-colors",
                  editPriority === p
                    ? PRIORITY_COLORS[p]
                    : "border-transparent text-muted-foreground/50 hover:text-muted-foreground"
                )}
                onClick={() => setEditPriority(p)}
                type="button"
              >
                {p}
              </button>
            ))}
          </div>
          <div className="flex gap-1">
            <Button size="xs" onClick={handleSaveEdit}>
              <Check className="size-3 mr-1" />
              Save
            </Button>
            <Button size="xs" variant="ghost" onClick={handleCancelEdit}>
              Cancel
            </Button>
          </div>
        </div>
      ) : (
        task.description && (
          <p className="mt-1 text-muted-foreground line-clamp-2" title={task.description}>{task.description}</p>
        )
      )}

      <div className="mt-2 flex items-center justify-between">
        <button
          className={cn(
            "rounded-full border px-2 py-0.5 text-[10px] font-medium transition-colors hover:brightness-125",
            STATUS_COLORS[task.status]
          )}
          onClick={() => onUpdate(task.id, { status: NEXT_STATUS[task.status] })}
          title={`Click to change to "${STATUS_LABELS[NEXT_STATUS[task.status]]}"`}
        >
          {STATUS_LABELS[task.status]}
        </button>

        {task.agentId && (
          <button
            className="flex items-center gap-1 text-[10px] text-primary hover:underline"
            onClick={() => onSelectAgent(task.agentId!)}
          >
            <ExternalLink className="size-2.5" />
            view agent
          </button>
        )}
      </div>
    </div>
  );
}

